import EXIF from 'exif-js';

// Helper function to check if coordinates are within range of target
const isLocationInRange = (lat, lng, targetLat, targetLng, range = 0.001) => {
    return Math.abs(lat - targetLat) < range && Math.abs(lng - targetLng) < range;
  };
  
  // Get current position using browser's Geolocation API
  const getCurrentPosition = () => {
    return new Promise((resolve, reject) => {
      if (!navigator.geolocation) {
        reject(new Error('Geolocation is not supported by your browser'));
      } else {
        navigator.geolocation.getCurrentPosition(
          (position) => {
            resolve({
              lat: position.coords.latitude,
              lng: position.coords.longitude
            });
          },
          (error) => {
            reject(error);
          },
          {
            enableHighAccuracy: true,
            timeout: 10000,
            maximumAge: 0
          }
        );
      }
    });
  };
  
  // Function to verify location using both EXIF and GPS
  const verifyLocation = async (file, targetLat, targetLng) => {
    // First try to get location from image EXIF data
    const exifPromise = new Promise((resolve) => {
      EXIF.getData(file, function() {
        const lat = EXIF.getTag(this, 'GPSLatitude');
        const lng = EXIF.getTag(this, 'GPSLongitude');
        
        if (lat && lng) {
          const decimalLat = lat[0] + lat[1]/60 + lat[2]/3600;
          const decimalLng = lng[0] + lng[1]/60 + lng[2]/3600;
          resolve({ lat: decimalLat, lng: decimalLng });
        } else {
          resolve(null);
        }
      });
    });
  
    try {
      // Try EXIF first
      const exifLocation = await exifPromise;
    //   if (exifLocation) {
    //     return {
    //       success: isLocationInRange(exifLocation.lat, exifLocation.lng, targetLat, targetLng),
    //       source: 'EXIF'
    //     };
    //   }
  
      // If no EXIF data, try current GPS location
      const currentLocation = await getCurrentPosition();
      return {
        success: isLocationInRange(currentLocation.lat, currentLocation.lng, targetLat, targetLng),
        source: 'GPS'
      };
    } catch (error) {
      throw new Error('Could not verify location. Please ensure location services are enabled.');
    }
  };
  
  export { verifyLocation };